import React, { useState } from "react";
import axios from "axios";
import "../styles/Upload.css";
import { HiOutlineSearchCircle } from "react-icons/hi"; 
import { RiDeleteBin6Line } from "react-icons/ri";

const Upload = () => {
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [fileType, setFileType] = useState(null); // Track if it's image or video

  const [resultUrl, setResultUrl] = useState(null);
  const [resultType, setResultType] = useState(null); // Track result type
  const [loading, setLoading] = useState(false);

  const handleFileChange = (selectedFile) => {
    if (selectedFile) {
      setFile(selectedFile);
      setPreview(URL.createObjectURL(selectedFile));

      // Determine if the file is a video or image based on its MIME type
      if (selectedFile.type.startsWith("video/")) {
        setFileType("video");
      } else {
        setFileType("image");
      }
    }
  };

  function handleDrop(e) {
    e.preventDefault();
    const droppedFile = e.dataTransfer.files[0];
    handleFileChange(droppedFile);
  }

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDetect = async () => {
    if (!file) {
      alert("Please upload a file first!");
      return;
    }
    const formData = new FormData();
    // Notice we changed the key to "file" to match the new backend code
    formData.append("file", file); 

    try {
      setLoading(true);
      const response = await axios.post(
        "http://127.0.0.1:5000/detect",
        formData,
        { headers: { "Content-Type": "multipart/form-data" } }
      );

      setResultUrl(`${response.data.result_url}?t=${new Date().getTime()}`);
      setResultType(response.data.type);
      setLoading(false);
    } catch (error) {
      console.error(error);
      alert("Detection failed!");
      setLoading(false);
    }
  };

  const handleClear = () => {
    setFile(null);
    setPreview(null);
    setFileType(null);
    setResultUrl(null);
    setResultType(null);
  };

  return (
    <div className="upload-container">
      <h2>📤 Upload Media</h2>
      <p>Analyze marine environments for plastic and debris using images or video.</p>

      <div
        className="drop-area"
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onClick={() => document.getElementById("fileInput").click()}
      >
        {preview ? (
          // IF VIDEO, SHOW VIDEO PLAYER. IF IMAGE, SHOW IMAGE.
          fileType === "video" ? (
            <video src={preview} controls className="preview-img" style={{ maxHeight: "400px" }} />
          ) : (
            <img src={preview} alt="Preview" className="preview-img" />
          )
        ) : (
          <p>Drag & Drop or Click to Upload Image/Video</p>
        )}
      </div>

      <input
        type="file"
        id="fileInput"
        hidden
        accept="image/*,video/*" /* Updated to accept video files */
        onChange={(e) => handleFileChange(e.target.files[0])}
      />

      <div className="button-group">
        <button className="glass-btn detect-btn" onClick={handleDetect} disabled={loading}>
          {loading ? (
            "Processing Media..." 
          ) : (
            <>
              <HiOutlineSearchCircle className="btn-icon pulse" /> Detect Objects
            </>
          )}
        </button>

        <button className="glass-btn clear-btn" onClick={handleClear}>
          <RiDeleteBin6Line className="btn-icon" /> Clear Workspace
        </button>
      </div>

      {loading && fileType === "video" && (
        <p style={{ color: "#00d2ff", marginTop: "15px" }}>
          <em>Note: Videos take significantly longer to process frame-by-frame. Please wait...</em>
        </p>
      )}

      {resultUrl && (
        <div className="result-section">
          <h3>✅ Analysis Complete</h3>
          {resultType === "video" ? (
            <video src={resultUrl} controls autoPlay className="result-img" style={{ maxHeight: "500px" }} />
          ) : (
            <img src={resultUrl} alt="Result" className="result-img" />
          )}
        </div>
      )}
    </div>
  );
};

export default Upload;
